const families=[['Encoded instructions','Hidden or encoded instructions','Critical'],['Relayed authority','Instructions passed between agents','Critical'],['Airdropped privilege tokens','Tokens mistaken for authority','Critical'],['Cross-user memory poisoning','Instructions planted in shared memory','Standard'],['Amount and decimals confusion','Unexpected amounts or units','Critical'],['Redefined approval','Persuasion that changes an approval','Critical'],['Control-plane injection','Untrusted control-plane instructions','Standard'],['Credential and secret exfiltration','Attempts to extract secrets','Critical']];
const view=document.querySelector('#view');const names={overview:'Overview',lookup:'Rating lookup',families:'Attack families',builders:'For builders',arena:'Arena'};const icon={overview:'◫',lookup:'⌕',families:'▤',builders:'◇',arena:'◎'};
const header=(title,desc,action='')=>`<div class="view-heading"><div><p class="overline">BOLLARD / ${title.toUpperCase()}</p><h1>${title}</h1><p>${desc}</p></div>${action}</div>`;
const empty=(title,body)=>`<div class="empty"><svg class="dash-icon" aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="8"/><circle cx="12" cy="12" r="4"/><path d="M12 11v2M11 12h2"/></svg><strong>${title}</strong><p>${body}</p></div>`;
const familyList=(filter='')=>families.map((f,i)=>({f,i})).filter(({f})=>f.join(' ').toLowerCase().includes(filter.toLowerCase())).map(({f,i})=>`<article class="family-item"><div class="family-icon">${String(i+1).padStart(2,'0')}</div><div><strong>${f[0]}</strong><p>${f[1]}</p></div><span class="tag">${f[2]}</span></article>`).join('');
function show(name){if(!names[name])name='overview';document.querySelectorAll('[data-view]').forEach(el=>{let active=el.dataset.view===name;el.classList.toggle('active',active);if(active)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current')});document.title=names[name]+' — Bollard';
if(name==='overview')view.innerHTML=header('Agent intelligence','A view of the proposed Bollard rating system.','<a class="primary" href="#lookup">Look up an agent ↗</a>')+`<div class="stats"><article class="glass stat"><div class="stat-top"><span>Published ratings</span><svg class="dash-icon" aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/></svg></div><strong>—</strong><small>Registry not connected</small></article><article class="glass stat"><div class="stat-top"><span>Attack families</span><svg class="dash-icon" aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M5 5h14v14H5zM8 9h8M8 12h8M8 15h5"/></svg></div><strong>8</strong><small>Specified for launch</small></article><article class="glass stat"><div class="stat-top"><span>Networks</span><svg class="dash-icon" aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M12 3 20 7.5v9L12 21 4 16.5v-9L12 3zM12 3v18M4 7.5l8 4.5 8-4.5"/></svg></div><strong>2</strong><small>Base + Robinhood Chain planned</small></article><article class="glass stat"><div class="stat-top"><span>Rating scale</span><svg class="dash-icon" aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="8"/><circle cx="12" cy="12" r="4"/><path d="M12 11v2M11 12h2"/></svg></div><strong>1–5</strong><small>Versioned, dated, expiring</small></article></div><div class="content-grid"><section class="glass panel activity"><div class="panel-head"><div><h2>Rating activity</h2><p>Published runs and their current status</p></div><span class="soft-tag">Awaiting connection</span></div>${empty('No ratings to show','Published runs will appear here when the registry is connected.')}</section><section class="glass panel guide"><div class="panel-head"><div><h2>Read the evidence</h2><p>A rating is a dated test result</p></div><span>↗</span></div><div class="guide-list"><div><span>01</span><p>Confirm the agent version</p></div><div><span>02</span><p>Review the families tested</p></div><div><span>03</span><p>Check expiry and dispute status</p></div></div><a href="#families" class="panel-link">Explore attack families <span>↗</span></a></section></div><section class="glass notice"><div><span class="notice-dot"></span><strong>Designed for evidence, not assurances.</strong><p>A rating cannot predict future behavior or cover losses. Keep your own limits.</p></div><a href="details.html">Full methodology ↗</a></section>`;
if(name==='lookup')view.innerHTML=header('Rating lookup','Search by name, address or ERC-8004 identity.')+`<section class="glass panel search-panel"><div class="panel-head"><div><h2>Find an agent</h2><p>Look up the latest versioned rating when the registry is connected.</p></div><span class="soft-tag">Not connected</span></div><form id="search-form" class="search-row"><label><span>Agent</span><input name="query" placeholder="Name, address or ERC-8004 ID" required></label><label><span>Network</span><select name="network"><option>Base</option><option>Robinhood Chain</option></select></label><button class="primary">Search ↗</button></form><div id="search-result">${empty('No registry connected','No live ratings are available yet.')}</div></section>`;
if(name==='families')view.innerHTML=header('Attack families','Eight families proposed for the launch corpus.')+`<section class="glass panel"><div class="panel-head"><div><h2>Explore the corpus</h2><p>Cases use simulated wallets and machine-checkable loss rules.</p></div><label class="filter"><span class="sr-only">Filter families</span><input id="filter" placeholder="Filter families…"></label></div><div class="family-grid" id="family-grid">${familyList()}</div><p class="fine-print">A test cannot cover every possible attack or predict future behavior.</p></section>`;
if(name==='builders')view.innerHTML=header('For builders','Prepare a local draft for a future rating run.')+`<div class="builder-grid"><section class="glass panel"><div class="panel-head"><div><h2>Agent details</h2><p>Saved in this browser. No request or payment is sent.</p></div><span class="soft-tag">Local draft</span></div><form id="builder-form" class="form-grid"><label>Agent name<input name="agent" placeholder="Agent name" required></label><label>Network<select name="network"><option>Base</option><option>Robinhood Chain</option></select></label><label>ERC-8004 agent ID<input name="agentId" placeholder="e.g. 123"></label><label>Version<input name="version" placeholder="e.g. v1.0"></label><label class="wide">Test endpoint<input name="endpoint" type="url" placeholder="https://"></label><div class="wide form-actions"><button class="primary">Save draft</button><button class="secondary" type="button" id="clear-draft">Clear draft</button><span id="saved" role="status"></span></div></form></section><section class="glass panel"><h2>What comes next</h2><div class="guide-list"><div><span>01</span><p>Register an ERC-8004 identity.</p></div><div><span>02</span><p>Expose a Bollard test endpoint.</p></div><div><span>03</span><p>Request a run for this version.</p></div><div><span>04</span><p>Review the rating and fix list.</p></div></div><div class="fee-card"><small>PROPOSED RUN FEE</small><strong>300 <small>USDC / USDG</small></strong><p>Per version; refund specified if no rating lands within 14 days.</p></div></section></div>`;
if(name==='arena')view.innerHTML=header('Arena','Public challenges are planned as a source of new test cases.')+`<section class="glass panel">${empty('No arenas available yet','Live sessions, bounties and attempt histories require the arena service.')}</section><section class="glass notice"><div><strong>From challenge to corpus</strong><p>Winning attacks are intended to become candidates for future test cases, subject to review.</p></div><a href="#families">Explore the corpus ↗</a></section>`;
let search=document.querySelector('#search-form');if(search)search.onsubmit=e=>{e.preventDefault();document.querySelector('#search-result').innerHTML=empty('Search unavailable','The rating service is not connected. No live search was performed.')};let filter=document.querySelector('#filter');if(filter)filter.oninput=()=>{document.querySelector('#family-grid').innerHTML=familyList(filter.value)||'<p class="fine-print">No matching attack families.</p>'};let form=document.querySelector('#builder-form');if(form){let saved={};try{saved=JSON.parse(localStorage.getItem('bollard-builder')||'{}')}catch{};for(const [k,v] of Object.entries(saved)){if(form.elements[k])form.elements[k].value=v}form.onsubmit=e=>{e.preventDefault();try{localStorage.setItem('bollard-builder',JSON.stringify(Object.fromEntries(new FormData(form))));document.querySelector('#saved').textContent='Draft saved in this browser.'}catch{document.querySelector('#saved').textContent='Could not save in this browser.'}};document.querySelector('#clear-draft').onclick=()=>{try{localStorage.removeItem('bollard-builder');form.reset();document.querySelector('#saved').textContent='Draft cleared.'}catch{document.querySelector('#saved').textContent='Could not clear the draft in this browser.'}}}}
window.addEventListener('hashchange',()=>show(location.hash.slice(1)||'overview'));show(location.hash.slice(1)||'overview');
